type L={country:Record<string,string>;terms:Record<string,string>;fields:Record<string,string>;results:Record<string,string>;intro:string;warning:string;formula:string;example:string;answer:string;faq:string;faqAnswer:string;options:Record<string,string>};
function globalModelFormula(kind: string, fields: Record<string, { label: string }>, results: Record<string, string>): string {
  const f = (name: string) => fields[name]?.label ?? name;
  const result = (key: string) => results[key] ?? key;
  if (kind === "sst") return `${f("amount")} × ${f("rate")} ÷ 100 = ${result("Tax amount")}; ${f("amount")} + tax = ${result("Tax-inclusive total")}.`;
  if (["vat", "gst", "sales"].includes(kind)) return `r = ${f("rate")} ÷ 100; ${result("Tax-exclusive amount")} × r = ${result("Tax amount")}; ${result("Tax-exclusive amount")} + ${result("Tax amount")} = ${result("Tax-inclusive total")}; ${result("Tax-inclusive total")} ÷ (1 + r) = ${result("Tax-exclusive amount")}.`;
  if (["income", "salaryTax", "gains", "corporate"].includes(kind)) return `${result("Estimated income tax")} = F(${f("income")}, ${f("filingStatus")}); ${result("Average tax rate")} = ${result("Estimated income tax")} ÷ ${f("income")}.`;
  if (["salary", "paycheck", "ni", "cpp", "cpf", "mpf", "epf", "socso", "sss", "philhealth", "pagibig", "social"].includes(kind)) return `${result("Estimated annual take-home pay")} = ${f("salary")} − ${result("Estimated income tax")} − ${result("Employee contributions")}; ${result("Estimated monthly take-home pay")} = ${result("Estimated annual take-home pay")} ÷ 12.`;
  if (["401k", "roth", "pension", "super", "kiwisaver", "rrsp"].includes(kind)) return `${result("Projected balance")} = FV(${f("annualContribution")}, ${f("employerRate")}, ${f("rate")}, ${f("years")}); ${result("Projected investment growth")} = ${result("Projected balance")} − ${result("Employer contributions")}.`;
  if (["gratuity", "endService"].includes(kind)) return `${result("Estimated gratuity")} = F(${f("salary")}, ${f("years")}, ${f("months")}).`;
  if (["stamp", "hkStamp"].includes(kind)) return `${result("Estimated property transfer duty")} = F(${f("propertyValue")}, ${f("buyer")}).`;
  if (kind === "freelancer") return `${result("Estimated taxable business profit")} = max(0, ${f("income")} − ${f("expenses")}); ${result("Estimated IRPF")} = ${result("Estimated taxable business profit")} × ${f("rate")} ÷ 100; ${result("Estimated annual social security")} = ${f("contributionBase")} × ${f("socialRate")} ÷ 100 × 12.`;
  return `The page calculation applies the visible inputs and configured reference assumptions. It does not infer personal, regional or eligibility details that are not entered.`;
}
