const resultFallback=(key:string,l:L)=>{const term=(k:string)=>l.terms[k]??l.fields.amount; if(key.includes("National Insurance"))return term("ni");if(key.includes("CPP")||key.includes("EI"))return term("cpp");if(key.includes("CPF"))return term("cpf");if(key.includes("MPF"))return term("mpf");if(key.includes("EPF"))return term("epf");if(key.includes("SOCSO"))return term("socso");if(key.includes("SSS"))return term("sss");if(key.includes("PhilHealth"))return term("philhealth");if(key.includes("Pag-IBIG"))return term("pagibig");if(key.includes("IRPF"))return term("freelancer");if(key.includes("gratuity")||key.includes("service"))return term("gratuity");if(key.includes("corporate"))return term("corporate");if(key.includes("stamp")||key.includes("duty"))return term("stamp");if(key.includes("gain"))return term("gains");if(key.includes("GST")||key.includes("tax-inclusive")||key.includes("Tax-exclusive")||key.includes("Tax amount"))return term("vat");if(key.includes("income tax")||key.includes("Taxable income")||key.includes("profit"))return l.fields.income;if(key.includes("rate"))return l.fields.rate;if(key.includes("employer"))return l.fields.employerRate;if(key.includes("employee")||key.includes("contribution")||key.includes("premium"))return l.fields.socialRate;if(key.includes("salary")||key.includes("pay"))return l.fields.salary;if(key.includes("balance")||key.includes("growth"))return term("pension");return l.fields.amount;};
const units:Record<Locale,Record<string,string>>={ko:{yr:"?",mo:"??"},en:{yr:"years",mo:"months"},ja:{yr:"?",mo:"??"},zh:{yr:"?",mo:"??"},es:{yr:"a?os",mo:"meses"},"pt-br":{yr:"anos",mo:"meses"},de:{yr:"Jahre",mo:"Monate"},fr:{yr:"ans",mo:"mois"},vi:{yr:"n?m",mo:"th?ng"},id:{yr:"tahun",mo:"bulan"},th:{yr:"??",mo:"?????"},"zh-tw":{yr:"?",mo:"??"},it:{yr:"anni",mo:"mesi"},nl:{yr:"jaar",mo:"maanden"},hi:{yr:"????",mo:"?????"}};
function basePhaseSixLocaleContent(locale:Locale):Partial<Record<(typeof globalCountryCalculatorSlugs)[number],LocalizedCalculatorContent>>{const l=copy[locale];return Object.fromEntries(globalCountryCalculatorRows.map(row=>{const page=getCalculatorPage(row.slug)!,country=l.country[row.code]!,name=`${country} ${l.terms[row.kind]!}`,fields=Object.fromEntries(page.fields.map(f=>[f.name,{label:l.fields[f.name]??l.fields.amount,...(f.unit?{unit:units[locale][f.unit]??f.unit}:{}),...(f.type==="number"?{placeholder:l.fields[f.name]??""}:{})}]));const options=Object.fromEntries(page.fields.filter(f=>f.options).map(f=>[f.name,Object.fromEntries(f.options!.map(o=>[o.value,l.options[o.value]??l.fields.amount]))]));const results=Object.fromEntries(resultKeys.map(key=>[key,l.results[key]??resultFallback(key,l)]));const exampleInput=Object.fromEntries(page.fields.map(f=>[f.name,f.defaultValue??(f.type==="select"?f.options?.[0]?.value??"":"0")]));const exampleOutcome=page.calculate(exampleInput);const exampleSummary="results" in exampleOutcome?exampleOutcome.results.slice(0,2).map(r=>`${new Intl.NumberFormat(locale).format(Number(r.value))}${r.unit?` ${r.unit}`:""}`).join(" / "):"";const title=`${name} (${countryRates[row.code]!.policyYear})`;return[row.slug,{name,shortName:name,title,description:`${name}. ${l.intro} ${l.warning}`,keywords:[name,`${country} ${l.terms[row.kind]}`],howTo:`${l.intro} ${l.warning}`,formula:globalModelFormula(row.kind,fields,results),example:{question:l.example,answer:`${l.answer}${exampleSummary?` ${exampleSummary}`:""}`},faqs:[{question:l.faq,answer:l.faqAnswer}],related:page.relatedCalculatorIds as LocalizedCalculatorContent["related"],fields,options,resultLabels:results,validation:l.warning,resultNote:l.warning} satisfies LocalizedCalculatorContent];})) as Partial<Record<(typeof globalCountryCalculatorSlugs)[number],LocalizedCalculatorContent>>;}

export function phaseSixLocaleContent(locale: Locale): Partial<Record<(typeof globalCountryCalculatorSlugs)[number], LocalizedCalculatorContent>> {
  const localized = basePhaseSixLocaleContent(locale);
  const labels = contentPatterns[locale];
  return Object.fromEntries(globalCountryCalculatorSlugs.map((slug) => {
    const page = getCalculatorPage(slug)!;
    const content = localized[slug]!;
    const fieldNames = page.fields.map((field) => content.fields[field.name]?.label ?? field.label).join(", ");
    const localizedFields = Object.fromEntries(Object.entries(content.fields).map(([key, value]) => [key, value.label]));
    const example = calculatorExample(page, locale, localizedFields, content.resultLabels);
    return [slug, {
      ...content,
      description: example ? `${purposeSentence(locale, page.fields.slice(0, 3).map((field) => content.fields[field.name]?.label ?? field.label), [example.primaryLabel])} ${content.description}` : content.description,
      howTo: `${content.name}: ${labels.inputs}: ${fieldNames}. ${content.howTo}`,
      example: example ? { question: `${content.name} — ${labels.exampleInput}: ${example.input}`, answer: `${labels.exampleResult}: ${example.result}. ${content.resultNote}` } : content.example,
      faqs: [{ question: `${content.name}: ${labels.inputQuestion}`, answer: `${labels.inputAnswer} ${fieldNames}. ${content.resultNote}` }, content.faqs[0]!],
    } satisfies LocalizedCalculatorContent];
  })) as Partial<Record<(typeof globalCountryCalculatorSlugs)[number], LocalizedCalculatorContent>>;
}
